async function loadAccess(){try{state.access=await api('/api/admin/access');var grants=state.access.grants||[];$('#grantsTable').innerHTML=grants.length?'<table class="table"><thead><tr><th>Projeto</th><th>Link</th><th>Permissão</th><th>Uso</th><th></th></tr></thead><tbody>'+grants.map(function(g){return '<tr><td><strong>'+esc(g.project_name)+'</strong></td><td>'+esc(g.label||'Compartilhamento')+'<br><small class="muted">'+(g.expires_at?'Expira '+esc(fmtDate(g.expires_at)):'Sem expiração')+'</small></td><td>'+esc(g.permission)+'</td><td>'+esc(g.use_count||0)+(g.max_uses?' / '+esc(g.max_uses):'')+'</td><td><button class="btn danger small" data-revoke-grant="'+esc(g.id)+'" '+(g.revoked_at?'disabled':'')+'>Revogar</button></td></tr>'}).join('')+'</tbody></table>':'<div class="empty">Nenhum link criado.</div>';$$('[data-revoke-grant]').forEach(function(b){b.onclick=async function(){if(!confirm('Revogar este link agora?'))return;try{await api('/api/admin/grants/'+b.dataset.revokeGrant+'/revoke',{method:'POST',body:'{}'});toast('Link revogado.','good');await loadAccess()}catch(e){toast(e.message,'bad')}}});var sessions=state.access.sessions||[];$('#sessionsTable').innerHTML=sessions.length?'<table class="table"><thead><tr><th>Conta</th><th>Criada</th><th>Última atividade</th><th>Validade</th><th></th></tr></thead><tbody>'+sessions.map(function(x){return '<tr><td><strong>'+esc(x.email||'Sessão')+'</strong></td><td>'+esc(fmtDate(x.created_at))+'</td><td>'+esc(fmtDate(x.last_seen_at))+'</td><td>'+esc(fmtDate(x.expires_at))+'</td><td><button class="btn danger small" data-revoke-session="'+esc(x.id)+'" '+(x.revoked_at?'disabled':'')+'>Encerrar</button></td></tr>'}).join('')+'</tbody></table>':'<div class="empty">Nenhuma sessão registrada.</div>';$$('[data-revoke-session]').forEach(function(b){b.onclick=async function(){if(!confirm('Encerrar esta sessão agora?'))return;try{await api('/api/admin/sessions/'+b.dataset.revokeSession+'/revoke',{method:'POST',body:'{}'});toast('Sessão encerrada.','good');await loadAccess()}catch(e){toast(e.message,'bad')}}})}catch(e){$('#grantsTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>';$('#sessionsTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
async function loadEmbeds(){try{var d=state.access||await api('/api/admin/access');state.access=d;var items=d.embeds||[];$('#embedsTable').innerHTML=items.length?'<table class="table"><thead><tr><th>Integração</th><th>Projeto</th><th>Domínios</th><th>Status</th><th></th></tr></thead><tbody>'+items.map(function(e){return '<tr><td><strong>'+esc(e.name)+'</strong><br><small class="muted">'+(e.expires_at?'Expira '+esc(fmtDate(e.expires_at)):'Sem expiração')+'</small></td><td>'+esc(e.project_name||'')+'</td><td>'+esc(e.domains||'—')+'</td><td>'+statusBadge(e.revoked_at?'disabled':e.status)+'</td><td><button class="btn danger small" data-revoke-embed="'+esc(e.id)+'" '+(e.revoked_at?'disabled':'')+'>Revogar</button></td></tr>'}).join('')+'</tbody></table>':'<div class="empty">Nenhum embed configurado.</div>';$$('[data-revoke-embed]').forEach(function(b){b.onclick=async function(){if(!confirm('Revogar esta integração imediatamente?'))return;try{await api('/api/admin/embeds/'+b.dataset.revokeEmbed+'/revoke',{method:'POST',body:'{}'});toast('Embed revogado.','good');state.access=null;await loadEmbeds()}catch(e){toast(e.message,'bad')}}})}catch(e){$('#embedsTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
$('#newEmbed').onclick=function(){fillProjectSelects();$('#embedForm').reset();$('#embedAccent').value='#b9862e';$('#embedMsg').textContent='';$('#embedDialog').showModal()};$('#embedForm').addEventListener('submit',async function(e){e.preventDefault();var body={projectId:$('#embedProject').value,name:$('#embedName').value,domains:[$('#embedDomain').value],mode:$('#embedMode').value,accent:$('#embedAccent').value,brandName:$('#embedBrandName').value||undefined,allowDownloads:$('#embedDownloads').checked};if($('#embedExpires').value)body.expiresAt=new Date($('#embedExpires').value).toISOString();$('#embedMsg').textContent='Criando…';try{var d=await api('/api/admin/embeds',{method:'POST',body:JSON.stringify(body)});$('#embedDialog').close();showResult('Embed criado','Use esta URL somente no domínio autorizado. O token pode ser revogado a qualquer momento.',d.url);state.access=null;await loadEmbeds()}catch(err){$('#embedMsg').textContent=err.message}});
async function loadTrash(){try{var d=await api('/api/admin/trash'),groups=[['clients','client','Clientes'],['projects','project','Projetos'],['captures','capture','Captações'],['assets','asset','Arquivos']],rows=[];groups.forEach(function(g){(d[g[0]]||[]).forEach(function(x){rows.push({kind:g[1],kindLabel:g[2],id:x.id,label:x.label,trashed_at:x.trashed_at})})});$('#trashTable').innerHTML=rows.length?'<table class="table"><thead><tr><th>Tipo</th><th>Item</th><th>Removido em</th><th></th></tr></thead><tbody>'+rows.map(function(x){return '<tr><td>'+esc(x.kindLabel)+'</td><td><strong>'+esc(x.label||x.id)+'</strong><br><small class="muted">'+esc(x.id)+'</small></td><td>'+esc(fmtDate(x.trashed_at))+'</td><td class="actions"><button class="btn gold small" data-restore-kind="'+esc(x.kind)+'" data-restore-id="'+esc(x.id)+'">Restaurar</button><button class="btn danger small" data-purge-kind="'+esc(x.kind)+'" data-purge-id="'+esc(x.id)+'">Excluir definitivamente</button></td></tr>'}).join('')+'</tbody></table>':'<div class="empty">A lixeira está vazia.</div>';$$('[data-restore-id]').forEach(function(b){b.onclick=async function(){try{await api('/api/admin/'+b.dataset.restoreKind+'s/'+b.dataset.restoreId+'/restore',{method:'POST',body:'{}'});toast('Item restaurado.','good');await reloadCore();await loadTrash()}catch(e){toast(e.message,'bad')}}});$$('[data-purge-id]').forEach(function(b){b.onclick=async function(){if(!confirm('EXCLUSÃO DEFINITIVA: este item e o vínculo correspondente no Drive não poderão ser restaurados. Continuar?'))return;try{await api('/api/admin/'+b.dataset.purgeKind+'s/'+b.dataset.purgeId+'/purge',{method:'DELETE'});toast('Item excluído definitivamente.','good');await loadTrash()}catch(e){toast(e.message,'bad')}}})}catch(e){$('#trashTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}$('#refreshTrash').onclick=loadTrash;
async function loadAudit(){try{var q=$('#auditSearch').value.trim();var d=await api('/api/admin/audit?limit=150'+(q?'&q='+encodeURIComponent(q):''));var items=d.items||[];$('#auditTable').innerHTML=items.length?'<table class="table"><thead><tr><th>Quando</th><th>Ação</th><th>Ator</th><th>Alvo</th><th>Resultado</th></tr></thead><tbody>'+items.map(function(a){return '<tr><td>'+esc(fmtDate(a.created_at))+'</td><td><strong>'+esc(a.action)+'</strong></td><td>'+esc(a.actor_type)+(a.actor_id?'<br><small class="muted">'+esc(a.actor_id)+'</small>':'')+'</td><td>'+esc(a.target_type||'')+(a.target_id?'<br><small class="muted">'+esc(a.target_id)+'</small>':'')+'</td><td>'+statusBadge(a.outcome||'success')+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">Nenhum evento encontrado.</div>'}catch(e){$('#auditTable').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}$('#auditGo').onclick=loadAudit;$('#auditSearch').addEventListener('keydown',function(e){if(e.key==='Enter')loadAudit()});
